(() => {
  const key='proyectat-curriculum-v1';
  let saved={data:{},versions:[]};
  try{const value=JSON.parse(localStorage.getItem(key)||'null');if(value&&value.data&&Array.isArray(value.versions))saved=value;}catch{}
  const escape=value=>String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fields=[['name','Nombre profesional','text',true],['headline','Disciplina y especialidad profesional','text',true],['place','Ciudad o ámbito de trabajo','text',false],['email','Correo de contacto','email',false],['phone','Teléfono de contacto','tel',false],['portfolio','Portfolio o web profesional','url',false],['summary','Perfil profesional','textarea',true],['experience','Experiencia laboral y artística','textarea',true],['projects','Obras, proyectos y actuaciones destacadas','textarea',false],['education','Formación y especialización','textarea',false],['skills','Habilidades técnicas y artísticas','textarea',false],['languages','Idiomas','textarea',false],['awards','Premios y reconocimientos','textarea',false]];
  const dialog=document.createElement('dialog');dialog.className='documents-dialog curriculum-dialog';dialog.setAttribute('aria-labelledby','curriculum-title');document.body.append(dialog);
  function persist(){try{localStorage.setItem(key,JSON.stringify(saved));return true;}catch{toast('No se ha podido guardar el currículum. Descarga una copia.');return false;}}
  const nav=document.createElement('button');nav.textContent='Currículums';nav.onclick=()=>open();document.querySelector('nav').append(nav);
  const cta=document.createElement('button');cta.className='outline';cta.textContent='Pásanos tus datos artísticos y laborales · Crear mi currículum ↗';cta.onclick=()=>{$('#profile-dialog').close();open();};$('#profile-form').after(cta);
  function open(tab='data',opportunityId=null){
    dialog.innerHTML='<button class="close" aria-label="Cerrar" data-close>×</button><div class="small-label">Tu trayectoria, con claridad</div><h2 id="curriculum-title">Crea tu currículum profesional.</h2><p>Reúne tu experiencia artística y laboral, formación y proyectos. El documento utiliza los datos que escribas; puedes adaptarlos para cada candidatura.</p><div class="document-tabs" role="tablist" aria-label="Currículum"><button role="tab" id="cv-data-tab" aria-controls="cv-panel" aria-selected="'+(tab==='data')+'">Mis datos</button><button role="tab" id="cv-created-tab" aria-controls="cv-panel" aria-selected="'+(tab==='created')+'">Currículums creados ('+saved.versions.length+')</button></div><div id="cv-panel" role="tabpanel"></div><p class="storage-note">Tus datos y currículums se guardan solo en este navegador. No se envían a Proyecta-T ni a las convocatorias. Incluye solo los datos que quieras mostrar en tu CV y descarga una copia para conservarla.</p>';
    const a=dialog.querySelector('#cv-data-tab'),b=dialog.querySelector('#cv-created-tab');function select(which){a.setAttribute('aria-selected',which==='data');b.setAttribute('aria-selected',which==='created');a.tabIndex=which==='data'?0:-1;b.tabIndex=which==='created'?0:-1;dialog.querySelector('#cv-panel').setAttribute('aria-labelledby',which==='data'?'cv-data-tab':'cv-created-tab');which==='data'?form(opportunityId):list(opportunityId);}a.onclick=()=>select('data');b.onclick=()=>select('created');[a,b].forEach(t=>t.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const target=e.key==='Home'?a:e.key==='End'?b:t===a?b:a;target.click();target.focus();}});select(tab);if(!dialog.open)dialog.showModal();
  }
  function form(opportunityId){const panel=dialog.querySelector('#cv-panel'),initial={name:profile.name||'',place:profile.place||'',headline:profileDisciplines().join(' · '),...saved.data};
    panel.innerHTML='<form id="curriculum-form"><div class="cv-form-grid">'+fields.map(([name,label,type,required])=>'<label class="field '+(type==='textarea'?'cv-wide':'')+'">'+label+(required?' *':'')+(type==='textarea'?'<textarea class="notes" name="'+name+'" maxlength="6000" '+(required?'required':'')+' placeholder="'+(name==='experience'?'Por cada experiencia: cargo o función, organización, fechas y aportación concreta. Separa las entradas con una línea en blanco.':name==='summary'?'Resume qué haces, tu especialidad y qué aportas en 3–5 líneas.':'Escribe los datos que quieres incluir; separa las entradas con una línea en blanco.')+'">'+escape(initial[name])+'</textarea>':'<input name="'+name+'" type="'+type+'" maxlength="200" '+(required?'required':'')+' value="'+escape(initial[name])+'">')+'</label>').join('')+'</div><label class="field">Vincular a una oportunidad (opcional)<select name="opportunity"><option value="">Currículum general</option>'+data.map(x=>'<option value="'+x.id+'">'+escape(x.title)+'</option>').join('')+'</select></label><label class="field">Nombre de esta versión<input name="versionName" maxlength="100" placeholder="Ej.: CV artístico · residencia Matadero" required></label><p class="storage-note">Presentación sobria y editorial, con secciones claras y formato A4. Omite campos vacíos y revisa fechas, cargos y enlaces antes de compartir.</p><div class="dialog-actions"><button class="outline" type="button" id="cv-save-data">Guardar mis datos</button><button class="primary" type="submit">Crear currículum profesional ↗</button></div><p id="cv-status" role="status"></p></form>';
    const f=panel.querySelector('form');if(opportunityId){f.elements.opportunity.value=String(opportunityId);const x=data.find(x=>x.id===opportunityId);if(x)f.elements.versionName.value=('CV · '+x.title).slice(0,100);}function collect(){return Object.fromEntries(fields.map(([name])=>[name,f.elements[name].value.trim()]));}panel.querySelector('#cv-save-data').onclick=()=>{saved.data=collect();panel.querySelector('#cv-status').textContent=persist()?'Datos guardados.':'No se han podido guardar los datos.';};f.onsubmit=e=>{e.preventDefault();const personal=collect();for(const name of ['name','headline','summary','experience']){if(!personal[name]){f.elements[name].setCustomValidity('Completa este campo.');f.elements[name].reportValidity();return;}}const opportunityId=f.elements.opportunity.value?+f.elements.opportunity.value:null;const version={id:crypto.randomUUID(),name:f.elements.versionName.value.trim(),data:personal,opportunityId,createdAt:new Date().toISOString()};if(!version.name)return;saved.data=personal;saved.versions.push(version);const stored=persist();open('created');preview(version.id);toast(stored?'Currículum creado y guardado':'Currículum creado. Descárgalo para conservarlo.');};fields.forEach(([name])=>f.elements[name].oninput=()=>f.elements[name].setCustomValidity(''));
  }
  function list(opportunityId=null){const panel=dialog.querySelector('#cv-panel');const versions=saved.versions.filter(v=>opportunityId===null||v.opportunityId===opportunityId);panel.innerHTML=versions.length?versions.map(v=>{const x=data.find(o=>o.id===v.opportunityId);return '<article class="document-row"><h3>'+escape(v.name)+'</h3><p>'+escape(x?x.title:'Currículum general')+'</p><span class="storage-note">'+new Date(v.createdAt).toLocaleDateString('es-ES')+'</span><div class="dialog-actions"><button class="outline" data-cv-preview="'+escape(v.id)+'">Ver currículum</button><button class="outline" data-cv-download="'+escape(v.id)+'">Descargar Word o PDF</button><button class="detail" data-cv-edit="'+escape(v.id)+'">Adaptar otra versión</button>'+(x?'<button class="detail" data-cv-offer="'+x.id+'">Ver oportunidad ↗</button>':'')+'</div></article>';}).join(''):'<div class="empty"><h3>Tu experiencia merece una buena presentación.</h3><p>Completa tus datos para crear tu primer currículum.</p></div>';panel.querySelectorAll('[data-cv-preview]').forEach(b=>b.onclick=()=>preview(b.dataset.cvPreview));panel.querySelectorAll('[data-cv-download]').forEach(b=>b.onclick=()=>download(b.dataset.cvDownload));panel.querySelectorAll('[data-cv-edit]').forEach(b=>b.onclick=()=>{saved.data={...saved.versions.find(v=>v.id===b.dataset.cvEdit).data};open();});panel.querySelectorAll('[data-cv-offer]').forEach(b=>b.onclick=()=>{dialog.close();showDetail(+b.dataset.cvOffer);});}
  function preview(id){const v=saved.versions.find(v=>v.id===id);if(v)ProyectaPreview(v.name,blocks(v));}
  function attachCV(id){const host=$('#workspace');if(host.querySelector('.cv-access'))return;const button=document.createElement('button');button.className='outline cv-access documents-access';const count=saved.versions.filter(v=>v.opportunityId===id).length;button.textContent=count?'Currículums para esta oportunidad ('+count+')':'Crear currículum para esta oportunidad ↗';button.onclick=()=>{$('#detail-dialog').close();open(count?'created':'data',id);};host.append(button);}
  const previousDetail=showDetail;showDetail=function(id){previousDetail(id);attachCV(id);};
  const previousWorkspace=renderWorkspace;renderWorkspace=function(id){previousWorkspace(id);attachCV(id);};
  function blocks(v){const d=v.data;const blocks=[{text:d.name,style:'title'},{text:d.headline,style:'heading'},{text:[d.place,d.email,d.phone,d.portfolio].filter(Boolean).join(' · '),style:'body'}];for(const [key,label] of fields.slice(6)){if(d[key])blocks.push({text:label,style:'heading'},{text:d[key],style:'body'});}return blocks;}
  function download(id){const v=saved.versions.find(v=>v.id===id);ProyectaExport.choose(v.name,blocks(v));}
})();
